/** A retired slug is held until exactly `ORG_SLUG_HOLD_DAYS` after it was retired. */
function isHeld(retiredAt: string, now: Date): boolean {
  return (
    Date.parse(retiredAt) + ORG_SLUG_HOLD_DAYS * MS_PER_DAY > now.getTime()
  );
}

/**
 * Resolves a slug to a live organization: its current slug first, then a slug
 * it retired that is still inside the hold window.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const current = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const retired = db
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .get();
  if (!retired || !isHeld(retired.retiredAt, new Date())) return null;

  const row = db
    .select()
    .from(organizations)
    .where(
      and(eq(organizations.id, retired.orgId), isNull(organizations.archivedAt)),
    )
    .get();
  return row ? toOrganization(row) : null;
}
''')
sub(p,'''export async function archiveOrg''','''/**
 * Changes the org's current slug to exactly `slug` and retires the one it
 * replaces. Refuses (without writing) a slug another org holds, as its current
 * slug (live or deleted) or as an unexpired retired slug.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const now = new Date();
    const stamp = toIsoTimestamp(now);

    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const clash = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
      .get();
    if (clash) throw new InvalidSlugError(slug, "is not available");

    const held = tx
      .select()
      .from(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, slug))
      .get();
    if (held && held.orgId !== orgId && isHeld(held.retiredAt, now)) {
      throw new InvalidSlugError(slug, "is not available");
    }

    // Taking a slug ends any retirement of it (ours, or another org's expired one).
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, slug))
      .run();

    if (current.slug !== slug) {
      tx.delete(organizationRetiredSlugs)
        .where(eq(organizationRetiredSlugs.slug, current.slug))
        .run();
      tx.insert(organizationRetiredSlugs)
        .values({ slug: current.slug, orgId, retiredAt: stamp })
        .run();
    }

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    return toOrganization(row);
  });
}

export async function archiveOrg''')
